#include<bits/stdc++.h>
using namespace std;

typedef unsigned long long ull;
typedef long long ll;

typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef pair<double, double> pdd;

typedef vector<int> vi;
typedef vector<vi> vvi;
typedef vector<vvi> vvvi;
typedef vector<pii> vpii;
typedef vector<pll> vpll;
typedef vector<pdd> vpdd;
typedef vector<ll> vll;

const int MAXN = 500 + 100;

ll mod;
struct mint {
    ll x;
    mint() : x(0) {}
    mint(ll _x) { x = _x >= 0 ? _x % mod : _x % mod + mod; }
    mint operator^(ll b) const {
        if(!b) return 1;
        mint tmp = (*this) ^ (b / 2);
        return b % 2 ? tmp * tmp * (*this) : tmp * tmp;
    }
    mint inv() const {
        static unordered_map<ll, ll> inv_dp;
        if(inv_dp.count(x)) return inv_dp[x];
        else if(inv_dp.size() < 100000) return mint(inv_dp[x] = ((*this) ^ (mod - 2)).x);
        else return (*this) ^ (mod - 2);
    }
    mint operator+(const mint &b) const { return (x + b.x) % mod; }
    mint operator-(const mint &b) const { return (x - b.x + mod) % mod; }
    mint operator*(const mint &b) const { return (x * b.x) % mod; }
    mint operator/(const mint &b) const { return (*this) * b.inv(); }
    mint & operator+=(const mint &b) { x = (x + b.x) % mod; return *this; }
    mint & operator-=(const mint &b) { x = (x - b.x + mod) % mod; return *this; }
    mint & operator*=(const mint &b) { x = (x * b.x) % mod; return *this; }
    mint & operator/=(const mint &b) { x = (x * b.inv().x) % mod; return *this; }
    bool operator==(const mint &b) const { return x == b.x; }
    bool operator!=(const mint &b) const { return x != b.x; }
};

mint comb[MAXN][MAXN];
void gen_comb(int n) {
    for(int i=0; i<=n; ++i) {
        comb[i][0]=comb[i][i]=1;
        for(int j=1; j<i; ++j) comb[i][j]=comb[i-1][j-1]+comb[i-1][j];
    }
}

mint A[MAXN], C[MAXN];
mint dp[MAXN][MAXN][2];
mint dpc[MAXN][MAXN][2];

ll s1(ll l, ll r) {
    if(l>r) return 0;
    return (l+r)*(r-l+1)/2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n,m;
    scanf("%lld %lld %lld", &n, &m, &mod);
    gen_comb(MAXN-1);

    A[0]=0; C[0]=1;
    A[1]=0; C[1]=2;
    for(int i=2; i<=m; ++i) {
        mint tmp=0, tmpc=0;
        for(int l=0; l<i; ++l) {
            ll r=i-1-l;
            tmp += C[l]*C[r]*(s1(1,l)+s1(1,r))*comb[i-1][l] + (A[l]*C[r]+A[r]*C[l])*comb[i-1][l]*(i+1);
            tmpc += C[l]*C[r]*(i+1)*comb[i-1][l];
        }
        A[i]=tmp; C[i]=tmpc;
    }

    dpc[0][0][0]=1;
    for(int i=1; i<=n; ++i) {
        for(int j=0; j<=m; ++j) {
            if(j>i) continue;
            dpc[i][j][0] = dpc[i-1][j][0] + dpc[i-1][j][1];
            for(int k=1; k<=j; ++k)
                dpc[i][j][1] += C[k]*comb[j][k]*dpc[i-k][j-k][0];
        }
    }

    for(int i=1; i<=n; ++i) {
        for(int j=0; j<=m; ++j) {
            if(j>i) continue;
            dp[i][j][0] = dp[i-1][j][0] + dp[i-1][j][1];
            for(int k=1; k<=j; ++k)
                dp[i][j][1] += A[k]*comb[j][k]*dpc[i-k][j-k][0] + dp[i-k][j-k][0]*C[k]*comb[j][k];
        }
    }

    printf("%lld\n", (dp[n][m][0]+dp[n][m][1]).x);
    return 0;
}
